{
  "name": "cremator-opencode",
  "version": "0.1.3",
  "private": false,
  "license": "Apache-2.0",
  "type": "module",
  "description": "CREMATOR adapter for the OpenCode 2.4.0 harness. Thin seam mapping, no policy.",
  "keywords": [
    "context-management",
    "context-window",
    "llm-agents",
    "coding-agents",
    "ai-agent",
    "compaction",
    "opencode"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zman406986/Agent-Memory-CREMATOR.git",
    "directory": "packages/adapters/opencode"
  },
  "homepage": "https://github.com/zman406986/Agent-Memory-CREMATOR#readme",
  "bugs": {
    "url": "https://github.com/zman406986/Agent-Memory-CREMATOR/issues"
  },
  "author": {
    "name": "zman406986",
    "url": "https://github.com/zman406986"
  },
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/server.d.ts",
      "default": "./dist/server.js"
    },
    "./plugin": {
      "types": "./dist/plugin.d.ts",
      "default": "./dist/plugin.js"
    },
    "./tui": {
      "default": "./ui/tui.js"
    },
    "./gui-experimental": {
      "default": "./ui/gui-experimental.cjs"
    }
  },
  "files": [
    "dist",
    "ui",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "engines": {
    "node": ">=22.16.0 <23.0.0 || >=24.0.0"
  },
  "scripts": {
    "prebuild": "node -e \"require('node:fs').rmSync('dist',{recursive:true,force:true})\"",
    "build": "tsc -p tsconfig.build.json",
    "prepack": "npm run build",
    "typecheck": "tsc --noEmit -p ."
  },
  "dependencies": {
    "@cremator/core": "^0.1.3"
  },
  "devDependencies": {
    "@opencode/ai": "2.4.0",
    "@opencode/plugin": "2.4.0",
    "@opencode/schema": "2.4.0"
  }
}

// The public entry for `cremator-opencode`. The shapes and the adapter's library surface
// live here; a host mounts the package through the `./server` subpath (see `src/server.ts`
// and the README), never through this file.
export const PACKAGE_NAME = 'cremator-opencode';
export { OPENCODE_FORGOTTEN_NODE_FIELD, OPENCODE_RECEIPT_OF_FIELD, deriveOpencodeRevert, opencodeReceiptEntryId, } from './apply.js';
export { OPENCODE_ASK_FLOOR_BYTES, OPENCODE_ASK_FRAME, OPENCODE_ASK_GRAMMAR, OPENCODE_ASK_PROMPT_GRAMMAR, askPromptOf, buildOpencodeAskBatch, buildOpencodePassPlan, isSeenUnit, readOpencodeAskAnswer, } from './ask.js';
export { OPENCODE_CAPABILITIES, OPENCODE_INACTIVE_L1_RULES, OPENCODE_L1_FACT_RESIDUALS, OPENCODE_L1_FACTS, createOpencodeCapabilities, } from './capabilities.js';
export { DEFAULT_OPENCODE_TOOL_TABLE, OPENCODE_TOOL_CLASSES, classifyOpencodeTool, createOpencodeToolClassifier, } from './classifier.js';
export { estimateRequestSplit, estimateRequestTokens, requestKindOf, requestPrefixOf, stepEndedRow, tokenUsageOf, usageObservation, } from './meter.js';
export { OPENCODE_ASK_REFUSED_RETRY, OPENCODE_ASK_RETRY, OPENCODE_ASK_TIMEOUT_MS, OPENCODE_MOUNT_DIRECTORY, OPENCODE_MOUNT_SEAMS, OPENCODE_PLUGIN_NAME, OPENCODE_PRUNE_COMMAND, OPENCODE_SUBAGENT_TOOL, OPENCODE_TEST_EXCLUDE_TOOLS, createFileJournalSink, createOpencodeMount, createOpencodePlugin, joinMountRoot, mountOptionsFromHost, readMountRootHolders, releaseMountRoot, } from './plugin.js';
export { OpencodeApplicationPort, createOpencodePort } from './port.js';
export { OPENCODE_NODE_PREFIX, OPENCODE_RECORD_ID_FIELD, OPENCODE_RECORD_PREFIX, deriveOpencodeSnapshot, opencodeMessageKey, opencodeMessageNodeId, opencodePartEvidence, opencodePartNodeId, opencodeToolNodeId, } from './snapshot.js';
export { OpencodeStorageError, defaultStorageRoot, openLedger, resolveStorage, sessionStorage, } from './storage.js';
export { OPENCODE_RECALL_TOOL_NAME, OPENCODE_TOOL_SPECS, createOpencodeTool, opencodeToolSpecs, recallOutputText, recallText, } from './tools.js';
